1	import { Suspense, lazy, useState } from 'react';
2	import { Route, Routes } from 'react-router-dom';
3	import { Spinner } from 'react-bootstrap';
4	import { AppNavbar } from './components/AppNavbar';
5	import { Footer } from './components/Footer';
6	import { CartDrawer } from './components/CartDrawer';
7	import { ErrorBoundary } from './components/ErrorBoundary';
8	import { ProtectedRoute } from './components/ProtectedRoute';
9	import { HomePage } from './pages/HomePage';
10	import { MenuPage } from './pages/MenuPage';
11	import { CheckoutPage } from './pages/CheckoutPage';
12	import { OrderConfirmationPage } from './pages/OrderConfirmationPage';
13	import { LoginPage } from './pages/LoginPage';
14	import { RegisterPage } from './pages/RegisterPage';
15	import { OrdersPage } from './pages/OrdersPage';
16	import { ProfilePage } from './pages/ProfilePage';
17	
18	/* ==========================================================================
19	 * REACT CONCEPT: lazy + Suspense (code splitting)
20	 *
21	 * React.lazy turns this import into a separate bundle that is fetched only when the route is
22	 * first visited. Customers — the overwhelming majority of visitors — never open /admin, so its
23	 * code should not be part of the JavaScript everyone downloads on the home page.
24	 *
25	 * Because the import is asynchronous, React needs something to show while it is in flight: that
26	 * is what the <Suspense fallback> below provides.
27	 *
28	 * The lazily-imported module must have a DEFAULT export.
29	 * ========================================================================== */
30	/*
31	 * Lazy, for the same reason the admin bundle is: twenty long answers plus their code samples are
32	 * pure dead weight for somebody who came here to order a pizza. It is a public route, just not one
33	 * on the critical path.
34	 */
35	const InterviewQuestionsPage = lazy(() =>
36	  import('./pages/InterviewQuestionsPage').then((m) => ({ default: m.InterviewQuestionsPage })),
37	);
38	
39	const AdminLayout = lazy(() => import('./pages/admin/AdminLayout'));
