const { chromium } = require('/Users/folaukaveinga/Github/claude_lovemesomecoding/lovemesomecoding_demo_project/pizza/pizza-react-frontend/node_modules/playwright');

const BASE = 'http://localhost:5173';

async function contact(page, label) {
  await page.getByRole('heading', { name: 'Checkout' }).waitFor();
  await page.waitForTimeout(1500); // let /api/auth/me and the address fetch settle
  return {
    name: await page.getByLabel('Name', { exact: true }).inputValue(),
    email: await page.getByLabel('Email', { exact: true }).inputValue(),
    label,
  };
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Sign in through the UI (the login form is prefilled with the demo customer).
  await page.goto(`${BASE}/login`);
  await page.getByLabel('Email').fill('customer@pizza.test');
  await page.getByLabel('Password').fill('pizza123');
  await page.getByRole('button', { name: 'Sign in', exact: true }).click();
  await page.waitForURL((u) => !u.pathname.startsWith('/login'));

  // Note what is already in the cart so cleanup removes only what we add.
  await page.getByRole('button', { name: /Open cart/ }).click();
  const before = await page.getByRole('button', { name: 'Remove' }).count();
  await page.keyboard.press('Escape');
  console.log('cart lines before:', before);

  await page.goto(`${BASE}/menu?type=PIZZA`);
  await page
    .getByRole('heading', { name: 'Pepperoni Pizza', exact: true })
    .locator('xpath=ancestor::div[contains(@class,"product-card")]')
    .getByRole('button', { name: 'Build it' })
    .click();
  await page.getByRole('dialog').getByRole('button', { name: 'Add to cart' }).click();
  await page.waitForTimeout(800); // cart save is debounced

  // Path A: cart drawer -> Checkout (client-side navigation).
  await page.getByRole('button', { name: /Open cart/ }).click();
  await page.getByRole('button', { name: 'Checkout' }).click();
  console.log(await contact(page, 'A: via cart drawer'));

  // Path B: refresh the checkout page (same as a bookmark / typed URL / reopened tab).
  await page.reload();
  const b = await contact(page, 'B: full load of /checkout');
  console.log(b);

  // Submit on path B, as the customer would.
  await page.getByRole('button', { name: /Continue to payment/ }).click();
  console.log('name error visible:', await page.getByText('Please tell us who the order is for.').isVisible());
  console.log('email error visible:', await page.getByText('We need a valid email to send the receipt.').isVisible());
  console.log('order created:', await page.getByText(/is reserved/).isVisible());
  await page.screenshot({ path: '/tmp/ticket3117/path-b.png', fullPage: true });

  // Timing evidence: how long /api/auth/me takes relative to the first render.
  // Cleanup: remove the pizza we added.
  await page.getByRole('button', { name: /Open cart/ }).click();
  const after = await page.getByRole('button', { name: 'Remove' }).count();
  if (after > before) await page.getByRole('button', { name: 'Remove' }).last().click();
  await page.waitForTimeout(800);
  console.log('cart lines after cleanup:', await page.getByRole('button', { name: 'Remove' }).count());

  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

